refsection.programlisting:
x = rand(1,10);
y = rand(1,10);
z = rand(1,10);
new_x = rand(1,10);
new_y = rand(1,10); 
new_z = rand(1,10); 
//example 1:

[tri,ptr] = delaunay_3(x,y,z);
dt3_insert_points(ptr,new_x,new_y,new_z);
new_tri = dt3_get_connectivity(ptr);
dt3_delete(ptr,"ptr"); // ptr is deleted here and cleared from scilab interpreter.
ptr
//example 2:
[tri1,ptr1] = delaunay_3(rand(1,10),rand(1,10),rand(1,10));
clear ptr1; // ptr1 is cleared from the sciab interpreter, but the memory is not freed yet.
dt3_delete(); // all pointers of dt3 will be deleted.
